    @OptIn(ExperimentalEncodingApi::class)
    private fun decode(b64: String): FloatArray {
        val raw = Base64.decode(b64)
        return FloatArray(raw.size) { idx -> ULAW_TABLE[raw[idx].toInt() and 0xFF] }
    }

    private val cache = mutableMapOf<String, ReferenceSample>()

    fun get(timbre: InstrumentTimbre, freqHz: Double = 440.0): ReferenceSample = when (timbre) {
        InstrumentTimbre.WARM_KEYS -> cache.getOrPut("WARM_KEYS") { ReferenceSample(69.0, decode(WARM_KEYS_B64)) }
        InstrumentTimbre.FLUTE -> cache.getOrPut("FLUTE") { ReferenceSample(69.0, decode(FLUTE_B64)) }
        InstrumentTimbre.REED -> cache.getOrPut("REED") { ReferenceSample(65.0, decode(REED_B64)) }
        InstrumentTimbre.BRASS -> cache.getOrPut("BRASS") { ReferenceSample(62.0, decode(BRASS_B64)) }
        InstrumentTimbre.STRING -> if (freqHz < 210.0) {
            cache.getOrPut("STRING_LOW") { ReferenceSample(45.0, decode(HARP_LOW_B64)) }
        } else {
            cache.getOrPut("STRING") { ReferenceSample(69.0, decode(STRING_B64)) }
        }
        InstrumentTimbre.BASS -> cache.getOrPut("BASS") { ReferenceSample(45.0, decode(BASS_B64)) }
    }
}
